CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX projects_owner ON projects(user_id);
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), name text NOT NULL, prefix text NOT NULL, key_hash text NOT NULL UNIQUE, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX api_keys_project ON api_keys(project_id);
CREATE TABLE endpoints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), name text NOT NULL, url text NOT NULL, secret_encrypted text NOT NULL, enabled boolean NOT NULL DEFAULT true, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX endpoints_project ON endpoints(project_id);
CREATE TABLE endpoint_events (endpoint_id uuid NOT NULL REFERENCES endpoints(id), event_type text NOT NULL, PRIMARY KEY(endpoint_id,event_type));
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id), type text NOT NULL, payload jsonb NOT NULL, idempotency_key text, request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,idempotency_key));
CREATE INDEX events_project_created ON events(project_id,created_at DESC);
CREATE TABLE deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id), endpoint_id uuid NOT NULL REFERENCES endpoints(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','succeeded','failed')), generation integer NOT NULL DEFAULT 0, attempt_count integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), locked_until timestamptz, lock_token uuid, last_status integer, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,endpoint_id));
CREATE INDEX deliveries_status_due ON deliveries(status,next_attempt_at);
CREATE INDEX deliveries_endpoint ON deliveries(endpoint_id,created_at DESC);
CREATE TABLE delivery_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid NOT NULL REFERENCES deliveries(id), generation integer NOT NULL, attempt integer NOT NULL, status_code integer, duration_ms integer NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(delivery_id,generation,attempt));
CREATE TABLE replays (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid NOT NULL REFERENCES deliveries(id), user_id uuid NOT NULL REFERENCES users(id), generation integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), delivery_id uuid NOT NULL REFERENCES deliveries(id), generation integer NOT NULL, attempt integer NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, UNIQUE(delivery_id,generation,attempt));
CREATE INDEX outbox_pending ON outbox_events(available_at) WHERE published_at IS NULL;
